fn solve(n: usize, s: Vec<char>) -> Vec<char> {
    let mut count_sf = 0;
    let mut count_fs = 0;

    for i in 1..n {
        if s[i - 1] == 'S' && s[i] == 'F' {
            count_sf += 1;
        } else if s[i - 1] == 'F' && s[i] == 'S' {
            count_fs += 1;
        }
    }

    if count_sf > count_fs {
        vec!['Y', 'E', 'S']
    } else {
        vec!['N', 'O']
    }
}

